/// Bounded, display-only inspection data for the Flutter import confirmation.
class BrushImportInspectionView {
  final String sourceFormat;
  final Uint8List sourceSha256;
  final BigInt bytes;
  final String fidelity;
  final String importerVersion;

  const BrushImportInspectionView({
    required this.sourceFormat,
    required this.sourceSha256,
    required this.bytes,
    required this.fidelity,
    required this.importerVersion,
  });

  @override
  int get hashCode =>
      sourceFormat.hashCode ^
      sourceSha256.hashCode ^
      bytes.hashCode ^
      fidelity.hashCode ^
      importerVersion.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BrushImportInspectionView &&
          runtimeType == other.runtimeType &&
          sourceFormat == other.sourceFormat &&
          sourceSha256 == other.sourceSha256 &&
          bytes == other.bytes &&
          fidelity == other.fidelity &&
          importerVersion == other.importerVersion;
}

