/// Bounded editable vector-stroke projection used by the vector inspector.
class VectorStrokeSummary {
  final BigInt id;
  final int pointCount;
  final Float32List points;
  final double minX;
  final double minY;
  final double maxX;
  final double maxY;

  const VectorStrokeSummary({
    required this.id,
    required this.pointCount,
    required this.points,
    required this.minX,
    required this.minY,
    required this.maxX,
    required this.maxY,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      pointCount.hashCode ^
      points.hashCode ^
      minX.hashCode ^
      minY.hashCode ^
      maxX.hashCode ^
      maxY.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VectorStrokeSummary &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          pointCount == other.pointCount &&
          points == other.points &&
          minX == other.minX &&
          minY == other.minY &&
          maxX == other.maxX &&
          maxY == other.maxY;
}
